'use strict';
const base5={render,handleAction,handleSubmit,settingsPage,attendancePage,overview,notificationModal,chatModal,searchModal,searchResults,modal,go,deck,platformSummary};
const v5={collapsed:false,group:null,pop:null};
modules.splice(modules.findIndex(m=>m.id==='work'),1);
try{v5.collapsed=localStorage.getItem('rm-v11-1-sidebar')==='small';}catch{}
Object.assign(data.policy,{carry:0,carryUntil:null,end:'16:00',breakStart:'12:00',breakEnd:'13:30',firstYear:'full'});
data.timeRecords={'jeck:2026-09-18':{in:'08:00',out:'16:00'},'eka:2026-09-18':{in:'08:03',out:'17:03'},'adovi:2026-09-18':{in:'10:00',out:'18:00'},'cantika:2026-09-18':{in:'07:58',out:null}};
const clockMinutes=s=>s?Number(s.slice(0,2))*60+Number(s.slice(3)):null;
const durationLabel=n=>`${Math.floor(n/60)}${t('j','h')} ${n%60}${t('m','m')}`;
function timeSummary(id,d=day()){
 const r=data.timeRecords[id+':'+d],start=clockMinutes(r?.in),end=clockMinutes(r?.out),bs=clockMinutes(data.policy.breakStart),be=clockMinutes(data.policy.breakEnd),target=clockMinutes(data.policy.end)-clockMinutes(data.policy.start);
 if(start==null||end==null)return {record:r,complete:false,target,late:start==null?0:Math.max(0,start-clockMinutes(data.policy.start)),status:t('Catatan belum lengkap','Incomplete record')};
 const span=end-start,rest=Math.max(0,Math.min(end,be)-Math.max(start,bs));return {record:r,complete:true,span,rest,net:span-rest,target,diff:span-target,late:Math.max(0,start-clockMinutes(data.policy.start)),status:span===target?t('Durasi terpenuhi','Duration met'):span<target?t('Di bawah durasi','Below duration'):t('Lebih dari target','Above duration')};
}
const oldAttendanceToday=attendanceToday;
attendanceToday=function(p){const previous=oldAttendanceToday(p);if(previous.label===t('Libur','Day off')||previous.label===t('Cuti','On leave'))return previous;const r=data.timeRecords[p.id+':'+day()];if(!r)return {label:t('Belum tercatat','Not recorded'),time:'—',color:''};const late=clockMinutes(r.in)>clockMinutes(data.policy.start)+data.policy.grace;return {label:late?t('Terlambat','Late'):t('Tepat waktu','On time'),time:r.in,color:late?'amber':'green'};};
leaveBalance=function(id){const year=Number(day().slice(0,4)),joined=Number(person(id).joined.slice(0,4)),q=data.policy.quota;const quota=(joined>year?0:joined===year&&data.policy.firstYear==='proportional'?Math.ceil(q*(13-Number(person(id).joined.slice(5,7)))/12):q)+(data.quotaAdjust[`${id}:${year}`]??(year===2026?data.quotaAdjust[id]||0:0));const a=data.leaves.filter(x=>x.staff===id&&x.type==='annual'&&x.start.startsWith(String(year))),sum=s=>a.filter(x=>x.status===s).reduce((n,x)=>n+x.days,0);const used=sum('used'),scheduled=sum('approved'),pending=sum('pending');return {quota,used,scheduled,pending,available:quota-used-scheduled-pending};};
showPolicy=function(){modal(t('Kebijakan kehadiran & cuti','Attendance & leave policy'),`<div class="row"><span>${t('Jatah tahunan','Annual allowance')}</span><strong>${data.policy.quota} ${t('hari','days')}</strong></div><div class="row"><span>${t('Tahun pertama','First year')}</span><strong>${data.policy.firstYear==='full'?t('Jatah penuh','Full allowance'):t('Proporsional','Proportional')}</strong></div><div class="row"><span>${t('Jadwal kehadiran','Attendance schedule')}</span><strong>${data.policy.start}–${data.policy.end}</strong></div><div class="row"><span>${t('Istirahat','Break')}</span><strong>${data.policy.breakStart}–${data.policy.breakEnd}</strong></div><p class="scope-note">${t('Rentang kehadiran sudah termasuk istirahat. Keterlambatan dan durasi ditampilkan terpisah.','Attendance duration includes the break. Lateness and duration are shown separately.')}</p>`);};
settingsPage=function(){if(!me().super)return '';const p=data.policy;return pageHead(t('Kebijakan kehadiran & cuti','Attendance & leave policy'),t('Aturan bersama, dengan catatan yang dapat ditelusuri.','Shared rules with traceable records.'))+`<section class="panel pad"><form data-form="v5-policy"><div class="form-grid">${field('quota',t('Jatah tahunan (hari)','Annual allowance (days)'),p.quota,'number','min="1" max="60" required')}<label class="field">${t('Jatah pada tahun pertama','First-year allowance')}<select name="firstYear"><option value="full" ${p.firstYear==='full'?'selected':''}>${t('Penuh','Full')}</option><option value="proportional" ${p.firstYear==='proportional'?'selected':''}>${t('Proporsional sejak bulan bergabung','Proportional from joining month')}</option></select></label>${field('start',t('Patokan masuk','Scheduled start'),p.start,'time','required')}${field('end',t('Patokan pulang','Scheduled end'),p.end,'time','required')}${field('breakStart',t('Mulai istirahat','Break starts'),p.breakStart,'time','required')}${field('breakEnd',t('Selesai istirahat','Break ends'),p.breakEnd,'time','required')}${field('grace',t('Toleransi keterlambatan (menit)','Late grace (minutes)'),p.grace,'number','min="0" max="120" required')}${field('notice',t('Anjuran pengajuan (hari kerja)','Suggested notice (working days)'),p.notice,'number','min="0" max="30" required')}${field('effective',t('Berlaku mulai','Effective from'),p.effective,'date',`required max="${day()}"`)}<div class="field full"><label>${t('Hari kerja','Working days')}</label><div class="inline">${t('Sen Sel Rab Kam Jum Sab Min','Mon Tue Wed Thu Fri Sat Sun').split(' ').map((s,i)=>`<label class="check"><input name="days" type="checkbox" value="${(i+1)%7}" ${p.days.includes((i+1)%7)?'checked':''}>${s}</label>`).join('')}</div></div>${reasonField()}</div><p class="scope-note">${t('Target dihitung dari rentang masuk–pulang, termasuk istirahat. Tahun pertama dapat langsung mengajukan cuti.','The target is the start-to-end span, including the break. Leave is available in the first year.')}</p>${formEnd(t('Simpan kebijakan','Save policy'))}</form></section>${panel(t('Kalender libur','Holiday calendar'),data.holidays.map(d=>`<div class="row">${date(d)}</div>`).join(''),btn(t('Tambah tanggal','Add date'),'holiday','','text'))}`;};
function dayTimeline(id){const s=timeSummary(id),r=s.record,att=attendanceToday(person(id));if(!r)return `<div class="time-empty">${badge(att.label,att.color)}<p>${t('Belum ada rentang kehadiran pada tanggal ini.','No attendance span recorded for this date.')}</p></div>`;return `<div class="time-heading"><strong>${r.in}<span> — </span>${r.out||'…'}</strong>${badge(att.label,att.color)}</div><div class="day-line"><span class="work-segment"></span><span class="break-segment"></span><span class="work-segment"></span></div><div class="time-labels"><span>${t('Masuk','Start')}</span><span>${data.policy.breakStart}–${data.policy.breakEnd} · ${t('istirahat','break')}</span><span>${r.out?t('Pulang','End'):t('Belum tercatat','Not recorded')}</span></div><div class="duration-line"><strong>${s.complete?durationLabel(s.span):'—'} <small>/ ${durationLabel(s.target)}</small></strong><span>${s.status}</span></div><div class="duration-track"><i style="width:${s.complete?Math.min(100,s.span/s.target*100):0}%"></i></div><p class="scope-note">${s.complete?`${t('Di luar istirahat','Excluding break')}: ${durationLabel(s.net)} · ${s.late>data.policy.grace?t('Terlambat','Late')+' '+durationLabel(s.late):t('Dalam toleransi masuk','Within start tolerance')}${s.diff>0?' · '+t('Lebih','Over')+' '+durationLabel(s.diff):s.diff<0?' · '+t('Kurang','Under')+' '+durationLabel(-s.diff):''}`:t('Durasi belum disimpulkan sampai catatan lengkap.','Duration is not assessed until the record is complete.')}</p>`;}
function workEvidence(id){return todayRecords().filter(x=>x.staff===id).slice(0,3).map(x=>`<div class="evidence-row"><span class="evidence-check">✓</span><div><strong>${esc(x.title)}</strong><small>${t('Tahapan selesai · catatan simulasi','Stage completed · simulated record')}</small></div><time>${x.time}</time></div>`).join('')||empty(t('Belum ada hasil tercatat hari ini','No outcomes recorded today'));}
personalOverview=function(id){const p=person(id),m=perf(id),prev=perf(id,'2026-07');return pageHead(t('Hari yang berarti.','Make today count.'),t('Waktumu, kontribusimu, dan ruang untuk bertumbuh.','Your time, contribution and room to grow.'))+`<div class="my-overview"><div class="personal-work"><section class="today-story"><div class="section-kicker">${date(day())} · WIB</div><h2>${t('Alur harimu','Your day at a glance')}</h2>${dayTimeline(id)}${btn(t('Lengkapi / koreksi catatan','Complete / correct record'),'v5-time-correct',`data-id="${id}"`,'text')}</section><section class="outcome-story"><div class="spread"><h2>${t('Jejak pekerjaan','Your work trail')}</h2><span class="outcome-number">${todayRecords().filter(x=>x.staff===id).length}</span></div>${workEvidence(id)}</section><section class="monthly-story"><div class="section-kicker">${month()} · ${t('ULASAN BULANAN','MONTHLY REFLECTION')}</div><h2>${t('Kualitas yang terus dirawat.','Keep quality in focus.')}</h2><div class="month-numbers"><div><small>${t('Juli','July')}</small><strong>${prev.total}</strong></div><span>→</span><div><small>${month()}</small><strong>${m.total}</strong></div><p>${t('tahapan selesai','stages completed')}<br>${m.corrections} ${t('koreksi internal','internal corrections')}</p></div>${weeklyChart(id)}<p class="reflection">${t(`${m.total} tahapan selesai, ${m.on} tepat waktu. Tinjau ${m.corrections} koreksi internal untuk mengenali bagian pemeriksaan yang perlu diperkuat. Jumlah hasil perlu dibaca bersama jenis pekerjaan dan kualitasnya.`,`${m.total} stages completed, ${m.on} on time. Review ${m.corrections} internal corrections to identify checks that need attention. Read output alongside work type and quality.`)}</p><small class="scope-note">${t('Ulasan AI simulasi dari catatan demo.','Simulated AI reflection based on demo records.')}</small><div>${btn(t('Lihat dasar ulasan','View supporting records'),'profile',`data-id="${id}"`,'text')}</div></section></div><aside class="personal-identity"><div class="photo-story">${portrait(p)}<div class="photo-caption"><button class="photo-award" data-action="v5-badge" title="${t('Lihat arti badge','View badge meaning')}">${icon('shield')}${t('Kontribusi tercatat','Traceable contribution')}</button><h2>${p.name}</h2><span>${personLabel(p)}</span></div></div><div class="personal-details"><span class="section-kicker">${t('INFORMASI PERSONAL','PERSONAL INFORMATION')}</span><dl><dt>${t('Bergabung','Joined')}</dt><dd>${date(p.joined)}</dd><dt>${t('Lokasi','Location')}</dt><dd>${esc(data.profiles[id].location)}</dd><dt>${t('Kontrak','Contract')}</dt><dd>PKWTT · ${t('Aktif','Active')}</dd></dl>${btn(t('Informasi pribadi','Personal information'),'personal',`data-id="${id}"`,'text')}${btn(t('Kontrak kerja','Employment contract'),'contract',`data-id="${id}"`,'text')}${btn(t('Kinerja lengkap','Full performance'),'profile',`data-id="${id}"`,'text')}</div></aside></div>`;};
overview=function(){if(!canTeam())return personalOverview(me().id);return pageHead(t('Kenali ritme tim.','Know your team’s rhythm.'),t('Kehadiran dan hasil nyata, dibaca berdampingan.','Attendance and real outcomes, side by side.'))+`<section class="team-rhythm"><div class="spread"><h2>${t('Hari ini bersama tim','Your team today')}</h2><small>${date(day())} · WIB</small></div>${people.map(p=>{const s=timeSummary(p.id);return `<div class="staff-rhythm-row"><button class="rhythm-person" data-action="person-overview" data-id="${p.id}">${avatar(p)}<strong>${p.name}<small>${personLabel(p)}</small></strong></button><div>${dayTimeline(p.id)}</div><button class="rhythm-outcome" data-action="person-overview" data-id="${p.id}"><strong>${todayRecords().filter(x=>x.staff===p.id).length}</strong><span>${t('tahapan selesai','stages completed')}</span><small>${data.tasks.filter(x=>x.handler===p.id&&x.stage!=='done'&&x.stage!=='queued').length} ${t('dalam penanganan','in progress')}</small></button></div>`;}).join('')}</section><div class="dashboard-grid">${deck('workload',t('Aktivitas & tanggung jawab','Activity & responsibility'),t('Antrean bersama tidak dijumlahkan antarstaf.','Shared queues are not summed across staff.'),workLoad(),7)}${deck('staff-activity',t('Aktivitas staf','Staff activity'),t('Tindakan yang tercatat hari ini.','Actions recorded today.'),staffEvents().slice(0,v3.expanded==='staff-activity'?30:4).map(e=>`<div class="activity">${avatar(person(e.who))}<div><strong>${person(e.who).name}</strong><p>${esc(L(e.text))}</p><small>${e.time} · ${e.obj}</small></div></div>`).join(''),5)}${me().super?deck('staff-approvals',t('Keputusan internal','Internal decisions'),t('Permohonan dan koreksi staf.','Staff requests and corrections.'),internalApprovals(),12):''}</div>`;};
queueContent=function(){const all=operationalTasks().filter(x=>x.stage==='queued');return `<div class="queue-detail-list">${['release','claim','support'].filter(k=>permission(k)!=='none').map(k=>{const tasks=all.filter(x=>x.kind===k);return `<section class="queue-group"><div class="spread"><h3>${L(kinds[k])}</h3><b>${tasks.length}</b></div>${tasks.slice(0,v3.expanded==='queue'?1000:2).map(x=>`<button class="queued-item" data-action="task" data-id="${x.id}"><span><strong>${esc(splitLabel(x.title))}</strong><small>${esc(x.label)} · ${x.id}</small><small>${t('Menunggu pemeriksaan','Awaiting review')} · ${date(x.created)}</small></span>${icon('arrow')}</button>`).join('')||`<small>${t('Tidak ada antrean baru','No new work')}</small>`}${tasks.length>2&&v3.expanded!=='queue'?btn(t(`Lihat ${tasks.length-2} lainnya`,`View ${tasks.length-2} more`),'expand','data-id="queue"','text'):''}</section>`;}).join('')}</div>`;};
deck=function(id,title,sub,body,size=6,action=''){const expanded=v3.expanded===id,horizontal=['progress','summary','workload'].includes(id);return base5.deck(id,title,sub,body,size,action).replace(/span-12/,expanded&&!horizontal&&size!==12?'span-'+size:'span-12').replace('grid-card ',`grid-card ${horizontal?'expand-horizontal':'expand-vertical'} `);};
const baseMiniChart=miniChart;
miniChart=function(values,color,desc){const max=Math.max(...values,1),p=values.map((v,i)=>[i*160/(values.length-1),37-v/max*31]);let d=`M${p[0][0]},${p[0][1]}`;for(let i=1;i<p.length;i++){const a=p[i-1],b=p[i],mid=(a[0]+b[0])/2;d+=` C${mid},${a[1]} ${mid},${b[1]} ${b[0]},${b[1]}`;}const uid='g'+Math.random().toString(36).slice(2);return `<svg class="mini-chart" viewBox="0 0 160 44" preserveAspectRatio="none" role="img" aria-label="${esc(desc)}"><title>${esc(desc)}</title><defs><linearGradient id="${uid}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".2"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="${d} L160,44 L0,44 Z" fill="url(#${uid})" stroke="none"/><path d="${d}" fill="none" stroke="${color}" stroke-width="1.2"/>${p.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="2" fill="var(--surface)" stroke="${color}"><title>${t('Periode','Period')} ${i+1}: ${values[i]}</title></circle>`).join('')}</svg>`;};
function closePop(){document.querySelector('#header-popover')?.remove();v5.pop=null;}
function convertPopover(kind){const dialog=$('#dialog'),body=dialog.querySelector('.dialog-body').innerHTML;dialog.close();dialog.innerHTML='';closePop();v5.pop=kind;$('.header').insertAdjacentHTML('beforeend',`<section id="header-popover" class="header-popover ${kind}" aria-label="${kind==='chat'?'Chat':t('Notifikasi','Notifications')}"><div class="popover-title"><h2>${kind==='chat'?'Chat':t('Notifikasi','Notifications')}</h2><div>${kind==='notifications'?btn(t('Tandai dibaca','Mark read'),'v5-read','','text'):''}${btn('×','v5-pop-close','aria-label="Close"','text')}</div></div><div class="popover-body">${body}</div></section>`);$('#header-popover button')?.focus();}
notificationModal=function(){base5.notificationModal();convertPopover('notifications');};
chatModal=function(){base5.chatModal();convertPopover('chat');};
modal=function(...args){closePop();$('#dialog').classList.remove('search-dialog');return base5.modal(...args);};
searchModal=function(){base5.searchModal();$('#dialog').classList.add('search-dialog');$('#dialog .scope-note').textContent=t('Cari menu, pekerjaan, staf, atau transaksi.','Find menus, work, staff or transactions.');};
searchResults=function(q){base5.searchResults(q);const query=q.trim().toLowerCase(),results=modules.filter(m=>m.id!=='work'&&allowedModule(m)&&(L(m.title)+' '+L(m.desc)).toLowerCase().includes(query)).slice(0,query?12:4);if(results.length)$('#search-results').insertAdjacentHTML('afterbegin',`<div class="search-section">${t('MODUL PLATFORM','PLATFORM MODULES')}</div>${results.map(m=>`<button class="search-result" data-action="v4-module" data-id="${m.id}">${icon('grid')}<span><strong>${L(m.title)}</strong><small>${L(groupNames[m.group])} · ${t('Penjelasan modul','Module outline')}</small></span>${icon('arrow')}</button>`).join('')}<div class="search-section">${t('PEKERJAAN & RUANG KERJA','WORK & WORKSPACE')}</div>`);};
attendancePage=function(){const body=base5.attendancePage();if(v3.attendanceTab==='policy'&&me().super)return body;return body+panel(t('Rentang kehadiran hari ini','Today’s attendance span'),dayTimeline(me().id),btn(t('Lengkapi / koreksi','Complete / correct'),'v5-time-correct',`data-id="${me().id}"`,'text'),t('Delapan jam sudah termasuk istirahat 12.00–13.30.','Eight hours includes the 12:00–13:30 break.'));};
function sidebar5(){const p=pages(),icons={ops:'release',royalty:'wallet',payments:'wallet',services:'support',system:'settings'};return `<aside class="side5 ${v5.collapsed?'small':''}" aria-label="${t('Navigasi utama','Main navigation')}"><div class="side-brand"><span class="mark">RM</span><strong>RILIS MUSIK</strong></div><button class="collapse-side" data-action="v5-collapse" aria-label="${t(v5.collapsed?'Perluas sidebar':'Perkecil sidebar',v5.collapsed?'Expand sidebar':'Collapse sidebar')}" title="${t('Ukuran sidebar','Sidebar size')}">${icon(v5.collapsed?'chevron':'menu')}</button><div class="side-scroll">${state.mode==='platform'?`<button class="side-link ${state.page==='dashboard'?'active':''}" data-action="v4-home" title="Dashboard">${icon('grid')}<span>Dashboard</span></button>${Object.keys(groupNames).filter(g=>modules.some(m=>m.group===g&&m.id!=='work'&&allowedModule(m))).map(g=>`<div class="side-group"><button class="side-link ${v5.group===g?'selected':''}" data-action="v5-group" data-id="${g}" aria-expanded="${v5.group===g}" title="${L(groupNames[g])}">${icon(icons[g])}<span>${L(groupNames[g])}</span><small>⌄</small></button>${v5.group===g?`<div class="side-children"><strong class="flyout-title">${L(groupNames[g])}</strong>${modules.filter(m=>m.group===g&&m.id!=='work'&&allowedModule(m)).map(m=>`<button data-action="v4-module" data-id="${m.id}" class="${state.page==='module'&&v4.module===m.id?'active':''}">${L(m.title)}</button>`).join('')}${g==='ops'&&me().super?`<button data-action="nav" data-page="workrules">${t('Aturan Pekerjaan','Work Rules')}</button>`:''}${g==='system'&&me().super?`<button data-action="nav" data-page="logs">${t('Riwayat simulasi','Simulation history')}</button>`:''}</div>`:''}</div>`).join('')}`:oldV4.nav().filter(([id])=>id!=='logs').map(([id,i])=>`<button class="side-link ${state.page===id?'active':''}" data-action="nav" data-page="${id}" title="${p[id]}">${icon(i)}<span>${p[id]}</span></button>`).join('')}</div><div class="side-person">${avatar(me())}<div><small>${t('Halo,','Hello,')}</small><strong>${me().name}</strong><small>${personLabel(me())}</small></div></div></aside>`;}
render=function(){v4.group=null;closePop();base5.render();const header=$('.header'),brand=$('.brand'),mode=$('.mode-switch'),tools=$('.tools');header.innerHTML=`<div class="header-top"><div class="header-left">${mode.outerHTML}<span class="header-path">${state.mode==='platform'?'Platform':'Staff'} <i>/</i> ${pages()[state.page]}</span></div>${tools.outerHTML}</div>`;$('#app').insertAdjacentHTML('afterbegin',sidebar5());document.documentElement.classList.toggle('sidebar-small',v5.collapsed);$('.version-pill').textContent='V5';$('.footer span').textContent='RILIS MUSIK · V5';document.title='Rilis Musik · V5';const alert=$('.focus-banner')||$('.calm-banner'),strip=$('.operational-strip');if(state.page==='dashboard'&&alert&&strip){const wrap=document.createElement('div');wrap.className='dashboard-pulse-row';alert.before(wrap);wrap.append(alert,strip);strip.querySelectorAll('span').forEach(e=>{if(e.textContent===t('Menunggu pihak lain','Waiting on others'))e.textContent=t('Menunggu · bagian penanganan','Waiting · included in progress');});}document.querySelectorAll('[data-action=notifications] .dot,[data-action=chat] .dot').forEach(e=>e.classList.add('red-dot'));};
function timeCorrectionForm(id){if(id!==me().id&&!me().super)return;const d=day(),r=data.timeRecords[id+':'+d]||{};modal(t('Koreksi catatan waktu','Correct time record'),`<p class="sub">${person(id).name} · ${date(d)}</p><form data-form="v5-time"><input type="hidden" name="staff" value="${id}">${field('date',t('Tanggal','Date'),d,'date',`required max="${day()}"`)}<div class="form-grid space">${field('in',t('Jam masuk','Arrival'),r.in||'08:00','time','required')}${field('out',t('Jam pulang','Departure'),r.out||'16:00','time','required')}</div>${reasonField()}${formEnd(t('Ajukan koreksi','Request correction'))}</form>`);}
handleAction=async function(b){const a=b.dataset.action,id=b.dataset.id;if(a==='v5-collapse'){v5.collapsed=!v5.collapsed;try{localStorage.setItem('rm-v11-1-sidebar',v5.collapsed?'small':'wide');}catch{}render();return;}if(a==='v5-group'){v5.group=v5.group===id?null:id;render();return;}if(a==='v5-pop-close'){closePop();return;}if(a==='v5-read'){if(!state.preview)visibleNotifications().forEach(n=>{if(!n.read.includes(me().id))n.read.push(me().id);});render();notificationModal();return;}if(a==='v5-badge'){modal(t('Kontribusi tercatat','Traceable contribution'),`<p class="reflection">${t('Catatan hasil kerja tersedia untuk periode Juli–Agustus. Badge ini menandai keterlacakan kontribusi, bukan ranking atau skor.','Work outcomes are documented for July–August. This badge marks traceability, not a ranking or score.')}</p>`);return;}if(a==='v5-time-correct'){timeCorrectionForm(id);return;}if(a==='correction-review'&&data.corrections.find(x=>x.id===id)?.times){const x=data.corrections.find(x=>x.id===id);if(!me().super)return;modal(t('Tinjau koreksi waktu','Review time correction'),`<p>${person(x.staff).name} · ${date(x.date)}</p><h3>${x.times.in}–${x.times.out}</h3><p>${esc(x.reason)}</p>${btn(t('Setujui','Approve'),'v5-time-approve',`data-id="${id}"`,'primary')}`);return;}if(a==='v5-time-approve'){if(!me().super||previewBlocked())return;const x=data.corrections.find(x=>x.id===id&&x.status==='pending');if(!x)return;Staff118.approveTime(data,id,day(),me().id);log(t('Koreksi waktu disetujui','Time correction approved'),x.reason);closeModal();render();return;}if(a==='expand'){const before=new Map([...document.querySelectorAll('[data-card]')].map(e=>[e.dataset.card,e.getBoundingClientRect()]));const target=document.querySelector(`[data-card="${id}"]`);const top=target?.getBoundingClientRect().top;await base5.handleAction(b);const after=document.querySelector(`[data-card="${id}"]`);if(after&&top!=null)window.scrollBy(0,after.getBoundingClientRect().top-top);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('[data-card]').forEach(el=>{const prev=before.get(el.dataset.card),now=el.getBoundingClientRect();if(prev&&now.width&&now.height)el.animate([{transformOrigin:'top left',transform:`translate(${prev.left-now.left}px,${prev.top-now.top}px) scale(${prev.width/now.width},${prev.height/now.height})`},{transformOrigin:'top left',transform:'none'}],{duration:320,easing:'cubic-bezier(.2,.8,.2,1)'});});return;}if(a==='mode'){v5.group=null;}return base5.handleAction(b);};
handleSubmit=async function(form){const kind=form.dataset.form,v=new FormData(form),get=k=>String(v.get(k)||'').trim();if(kind==='v5-time'){if(previewBlocked(true))return;const id=get('staff');if(id!==me().id&&!me().super)return;const start=clockMinutes(get('in')),end=clockMinutes(get('out'));if(end<=start||get('date')>day()||!get('reason'))return feedback(t('Periksa jam pulang, tanggal, dan alasan.','Check departure time, date and reason.'));data.corrections.push({id:'TC-'+Date.now(),staff:id,date:get('date'),reason:get('reason'),requested:'present',status:'pending',times:{in:get('in'),out:get('out')},policy118:Staff118.policyForDate(data,id,get('date')),before118:{in:data.timeRecords[id+':'+get('date')]?.in||null,out:data.timeRecords[id+':'+get('date')]?.out||null}});closeModal();render();toast(t('Koreksi menunggu persetujuan.','Correction awaiting approval.'));return;}if(kind==='v5-policy'){if(!me().super||previewBlocked(true))return;const days=v.getAll('days').map(Number),quota=Number(get('quota')),start=clockMinutes(get('start')),end=clockMinutes(get('end')),bs=clockMinutes(get('breakStart')),be=clockMinutes(get('breakEnd'));if(!days.length||end<=start||be<=bs||bs<start||be>end||quota<1||quota>60||!get('reason'))return feedback(t('Periksa jadwal, jatah, hari kerja, dan alasan.','Check schedule, allowance, days and reason.'));Staff118.changePolicy(data,people,{...data.policy,quota,firstYear:get('firstYear'),start:get('start'),end:get('end'),breakStart:get('breakStart'),breakEnd:get('breakEnd'),grace:Number(get('grace')),notice:Number(get('notice')),effective:get('effective'),days},day());log(t('Kebijakan diperbarui','Policy updated'),get('reason'));render();toast(t('Kebijakan disimpan dalam simulasi.','Policy saved in simulation.'));return;}return base5.handleSubmit(form);};
guide=function(){modal(t('Selamat datang di V5','Welcome to V5'),`<p class="reflection">${t('Sidebar kembali. Detail pekerjaan lebih dekat.','The sidebar returns. Work details come closer.')}</p><ol class="guide-list"><li>${t('Perkecil sidebar melalui tombol di bawah logo.','Collapse the sidebar below the logo.')}</li><li>${t('Buka detail antrean dan perluas kartu untuk melihat lebih banyak pekerjaan.','Open queue details and expand cards for more work.')}</li><li>${t('Coba Staff sebagai Adovi: masuk 10.00, pulang 18.00; durasi terpenuhi meski terlambat.','Try Staff as Adovi: 10:00–18:00; duration met despite a late start.')}</li><li>${t('Cantika memiliki catatan pulang belum lengkap. Coba ajukan koreksi dan setujui sebagai Super Admin.','Cantika has a missing departure record. Request a correction and approve as Super Admin.')}</li></ol><p class="scope-note">${t('Seluruh data, pesan, ulasan AI, dan dokumen adalah simulasi lokal.','All records, messages, AI reviews and documents are local simulations.')}</p>`);};
document.addEventListener('click',e=>{if(v5.pop&&!e.target.closest('#header-popover')&&!e.target.closest('[data-action="chat"],[data-action="notifications"],[data-action="v5-read"],[data-action="search"]'))closePop();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePop();if($('#dialog').classList.contains('search-dialog')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const a=[$('#search-input'),...document.querySelectorAll('.search-result')],i=a.indexOf(document.activeElement);a[(i+(e.key==='ArrowDown'?1:a.length-1))%a.length]?.focus();}});
const initialBefore5=initial;
const timelineBefore5=dayTimeline;
dayTimeline=function(id){let html=timelineBefore5(id);const s=timeSummary(id);if(!s.record)return html;if(!s.complete)return html.replace(/<div class="day-line">[\s\S]*?<\/div>/,'<div class="day-line" style="opacity:.3;background:repeating-linear-gradient(90deg,var(--muted) 0 4px,transparent 4px 8px)"></div>');const start=clockMinutes(s.record.in),end=clockMinutes(s.record.out),bs=clockMinutes(data.policy.breakStart),be=clockMinutes(data.policy.breakEnd),before=Math.max(0,Math.min(end,bs)-start),after=Math.max(0,end-Math.max(start,be));const track=`<div class="day-line" role="img" aria-label="${t('Durasi di luar istirahat','Duration excluding break')} ${durationLabel(s.net)}">${before?`<span class="work-segment" style="flex:${before}"></span>`:''}${s.rest?`<span class="break-segment" style="flex:${s.rest}"></span>`:''}${after?`<span class="work-segment" style="flex:${after}"></span>`:''}</div>`;return html.replace(/<div class="day-line">[\s\S]*?<\/div>/,track);};
initial=function(){const d=initialBefore5();Object.assign(d.policy,{carry:0,carryUntil:null,end:'16:00',breakStart:'12:00',breakEnd:'13:30',firstYear:'full'});d.timeRecords={'jeck:2026-09-18':{in:'08:00',out:'16:00'},'eka:2026-09-18':{in:'08:03',out:'17:03'},'adovi:2026-09-18':{in:'10:00',out:'18:00'},'cantika:2026-09-18':{in:'07:58',out:null}};return d;};
